#!/usr/bin/env bash
# Reproduce S8 v2x-track submission 's8v' (model-v2x-track/routed-g13): test-frame inference with the exact
# checkpoints, merge with the committed model.yaml, compare with the scored zip, repackage the same 50 frames, kit check.
# Generated by common/tools/reproduce_submission.py; scored zip model-v2x-track/routed-g13/submissions/2026-10-30_s8v/v2x_s8v_submission.zip (md5 b9c82e3de0c37babf146549eeedabbf6).
# Usage: CUDA_VISIBLE_DEVICES=0 bash model-v2x-track/routed-g13/test/reproduce_s8v.sh
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/../../.."      # the repository root (portable)
source common/env/activate.sh
OUT=model-v2x-track/routed-g13/test/output/repro_s8v
mkdir -p $OUT
# member bagpv5: seed bag model-v2x-track/bag-pvrcnnpp-ros-g1v5 (3 seeds, TTA off); seeds: model-v2x-track/pvrcnnpp-ros-g1v5/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth (md5 4bceaa59aeb5c62520b334a0c20525d5), model-v2x-track/pvrcnnpp-ros-g1v5-s2/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth (md5 f36f0300036e489bde87e30fd17e694d), model-v2x-track/pvrcnnpp-ros-g1v5-s3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth (md5 106fcb7d15e72ef1efcb10bfc90b543c)
python common/tools/bag_predictions.py model-v2x-track/bag-pvrcnnpp-ros-g1v5 --kit --variant plain --refresh --cache-dir $OUT/bag_bagpv5 --out $OUT/predictions_bagpv5.json
# member bagvr5_tta: seed bag model-v2x-track/bag-voxelrcnn-ros-g1v5 (3 seeds, TTA flip4+yaw+z); seeds: model-v2x-track/voxelrcnn-ros-g1v5/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth (md5 a90a13b7e29706bb06b8a435bf0b3eac), model-v2x-track/voxelrcnn-ros-g1v5-s2/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth (md5 be6acbf7d91fea91235ff2d89fc8dbae), model-v2x-track/voxelrcnn-ros-g1v5-s3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth (md5 3a4f716b778dc88d4b030e8c2f3ac756)
python common/tools/bag_predictions.py model-v2x-track/bag-voxelrcnn-ros-g1v5 --kit --variant tta --refresh --cache-dir $OUT/bag_bagvr5_tta --out $OUT/predictions_bagvr5_tta.json
# member pp5_tta: model-v2x-track/pointpillars-g1v5, checkpoint md5 62070b22bce0641b803187bda4b113e9
python common/tools/pcdet_predict.py model-v2x-track/pointpillars-g1v5 --ckpt model-v2x-track/pointpillars-g1v5/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-v2x-track/pointpillars-g1v5/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_pp5_tta.json
# member pvros4s2_tta: model-v2x-track/pvrcnnpp-ros-g1v4-s2, checkpoint md5 30b8d6036c6f2c4b8d9de562d0f2e6a5
python common/tools/pcdet_predict.py model-v2x-track/pvrcnnpp-ros-g1v4-s2 --ckpt model-v2x-track/pvrcnnpp-ros-g1v4-s2/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-v2x-track/pvrcnnpp-ros-g1v4-s2/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_pvros4s2_tta.json
# member vrros4_tta12: model-v2x-track/voxelrcnn-ros-g1v4, checkpoint md5 b85264eaec17f167f34b0185acce9313
python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-ros-g1v4 --ckpt model-v2x-track/voxelrcnn-ros-g1v4/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-v2x-track/voxelrcnn-ros-g1v4/test/postprocess_tta12.yaml --tta flip4+yaw+z+scale --out $OUT/predictions_vrros4_tta12.json
# member vrros_tta12: model-v2x-track/voxelrcnn-ros-g1v3, checkpoint md5 5677c039b8cc33a058b045f732c687de
python common/tools/pcdet_predict.py model-v2x-track/voxelrcnn-ros-g1v3 --ckpt model-v2x-track/voxelrcnn-ros-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-v2x-track/voxelrcnn-ros-g1v3/test/postprocess_tta12.yaml --tta flip4+yaw+z+scale --out $OUT/predictions_vrros_tta12.json
python common/tools/route_predictions.py merge model-v2x-track/routed-g13 --pred bagpv5=$OUT/predictions_bagpv5.json --pred bagvr5_tta=$OUT/predictions_bagvr5_tta.json --pred pp5_tta=$OUT/predictions_pp5_tta.json --pred pvros4s2_tta=$OUT/predictions_pvros4s2_tta.json --pred vrros4_tta12=$OUT/predictions_vrros4_tta12.json --pred vrros_tta12=$OUT/predictions_vrros_tta12.json --out $OUT/predictions.json
python common/tools/reproduce_submission.py model-v2x-track/routed-g13 --tag s8v --compare $OUT/predictions.json
# the 50 realism frames: from the synthetic corpus when it is present (a check that it still gives the scored frames),
# else from the scored zip itself (a fresh clone has no corpus; the zip is in git)
if [ -d "$BDC_DATA/v2x-track/pcdet/g1-v5/points" ]; then SYN=(--syn-split val --syn-list model-v2x-track/routed-g13/submissions/2026-10-30_s8v/synthetic_ids.txt); else SYN=(--syn-zip model-v2x-track/routed-g13/submissions/2026-10-30_s8v/v2x_s8v_submission.zip --syn-list model-v2x-track/routed-g13/submissions/2026-10-30_s8v/synthetic_ids.txt); fi
python common/tools/package_submission.py model-v2x-track/routed-g13 --tag repro-s8v --pred $OUT/predictions.json --synthetic pcdet/g1-v5 "${SYN[@]}" --team ${BDC_TEAM:-KarmaRV} --ckpt 'reproduction of s8v' --reproduction
Z=model-v2x-track/routed-g13/test/output/repro-s8v/submission.zip
python common/tools/check_submission.py --track v2x $Z --official
python common/tools/reproduce_submission.py model-v2x-track/routed-g13 --tag s8v --compare-zip $Z     # predictions and frames against the scored zip
